const docs:LibraryDoc[]=[
{id:"news-ecosystem",category:"News",title:"Introducing the VANT ecosystem",type:"PRODUCT OVERVIEW · ECOSYSTEM",summary:"A connected technology ecosystem taking shape around intelligent work, personal learning, and purposeful assistance.",date:"VANT TECHNOLOGIES · COMPANY JOURNAL",sections:[
{heading:"A platform built around possibility",paragraphs:["VANT began with a practical ambition: make capable AI useful in the everyday work of people, teams, businesses, and learners. The goal was never simply to place a chatbot on a page. It was to build a connected work platform in which conversation, tools, projects, collaboration, memory, and learning could work together.","The product and company identity evolved through several naming and positioning stages—from VANT, to VANT AI, to VANT Intelligence, and toward VANT Technologies. Each step reflected a broader view of the work: not just an AI interface, but a technology company developing an ecosystem of connected capabilities."]},
{heading:"One ecosystem, distinct experiences",paragraphs:["The ecosystem is organized around three recognizable experiences. VANT AI Work Platform is the productivity and collaboration environment. VANT Education focuses on turning learning materials into useful study resources. MOTE.EXE is the assistant identity and guardian presence designed to make the system feel coherent and approachable without becoming distracting."],bullets:["VANT AI Work Platform — AI chat, projects, tools, CoWork, integrations, dashboard, and persistent memory.","VANT Education — notes summarization, study-guide generation, flashcards, practice quizzes, study planning, and assignment tracking.","MOTE.EXE — VANT's watchful assistant identity, intended to provide a consistent presence across the ecosystem."]},
{heading:"Built in stages",paragraphs:["The work has progressed through interface prototypes, authentication and state management, model integration, collaboration concepts, student tools, corporate identity, and the public-facing VANT Technologies website. The ecosystem is still evolving. Individual features may be at different stages of design, preview, implementation, or production readiness.","This library records the thinking and engineering behind that progress. It distinguishes a proposed architecture from a shipped feature, and a development preview from a production capability. That distinction matters: the purpose of the library is to make the work understandable, not to overstate it."]},
{heading:"The principle",paragraphs:["We build intelligent technology that moves people forward. We believe AI and thoughtful design can make work more capable, learning more personal, and ambitious ideas more achievable. Our vision is a future where technology expands human possibility—with purpose, responsibility, and room for everyone to grow."]}
]},
{id:"news-education",category:"News",title:"Making learning more personal with VANT Education",type:"PRODUCT SPOTLIGHT · LEARNING",summary:"A student-focused toolkit designed to turn notes, assignments, and study goals into structured learning workflows.",date:"VANT TECHNOLOGIES · PRODUCT JOURNAL",sections:[
{heading:"From raw notes to usable knowledge",paragraphs:["VANT Education grew from a simple observation: students often have information, but turning that information into something they can study takes time. Notes need to be organized, key ideas identified, concepts recalled, and deadlines managed. The product direction is to make those steps easier without removing the learner from the process.","The Notes Summarizer and Study-Guide Generator form the foundation. They are intended to transform pasted or supplied notes into clearer summaries and structured guides that learners can review, revise, and use as a starting point for deeper study."]},
{heading:"A connected study toolkit",paragraphs:["The planned toolset extends beyond summarization. Flashcards support active recall; Practice Quiz supports self-checking; Study Planner helps organize sessions; and Assignment Tracker gives learners a place to monitor work and due dates."],bullets:["Notes Summarizer — condense source notes into organized key points.","Study-Guide Generator — restructure notes into a review-friendly guide.","Flashcards — turn important concepts into recall prompts.","Practice Quiz — generate questions for self-assessment.","Study Planner — organize study time and priorities.","Assignment Tracker — keep assignments and deadlines visible.","Vant Skills — a broader learning-support concept within the education experience."]},
{heading:"Designing for learners",paragraphs:["The student dashboard direction uses a softer off-white foundation and a distinct purple accent for the Students & Learning identity. The aim is to feel calm and supportive while remaining part of the larger VANT product family.","Education features should be transparent about their source material. A generated explanation or quiz is a learning aid, not a substitute for the original lesson, teacher guidance, or the student's own judgment. Learners should be able to return to the notes that informed an output and correct or refine it."]},
{heading:"A product that grows with its users",paragraphs:["VANT Education belongs in the same ecosystem as the work platform, but it should not feel like a business dashboard repainted for students. Its navigation, language, and workflows should respect the different rhythms of learning: explore, understand, practice, reflect, and improve."]}
]},
{id:"architecture-semantic",category:"Architectures",title:"VANT Semantic Architecture",type:"SYSTEM ARCHITECTURE · SYS-001",summary:"One intelligence. Multiple capabilities. A proposed shared semantic core connecting context, reasoning, memory, orchestration, and interfaces.",date:"VANT RESEARCH DIVISION · ARCHITECTURE NOTE",sections:[
{heading:"Architectural intent",paragraphs:["The VANT Semantic Architecture is a proposed ecosystem-level design. It describes how a shared intelligence layer could coordinate context, reasoning, memory, orchestration, specialist capabilities, execution, and connected interfaces across VANT experiences.","The central idea is not that every product must become one monolithic application. It is that different capabilities can share a common understanding of user intent and relevant context while remaining modular, independently governed, and connected through explicit interfaces."]},
{heading:"The semantic core",paragraphs:["At the center is a semantic core: the conceptual layer responsible for interpreting requests in context and coordinating the capabilities needed to respond. It is surrounded by functional layers rather than treated as a single magical model."],bullets:["Context layer — retrieval and understanding of relevant conversation, project, and task context.","Memory — persistent information that can be recalled when relevant and permitted.","Reasoning — model services used to analyze, plan, and formulate responses.","Orchestration — routing, sequencing, and coordination of specialist capabilities.","Capabilities — CoWork, Education, Tools, and other product functions.","Execution layer — approved actions and integrations, bounded by permissions and review.","Interfaces — applications, connectors, and user-facing surfaces."]},
{heading:"A modular system, not a claim of completion",paragraphs:["This diagram is a direction for system design, not a statement that one deployed semantic service currently coordinates every VANT product. Some parts describe existing product concepts or implementation areas; others are future-facing architecture. The boundary between them should remain explicit in engineering documentation.","A modular design makes it easier to change model providers, improve retrieval, isolate failures, and evolve product experiences without rewriting the entire platform. It also creates a place to define contracts: what context a capability receives, what it may return, what actions it may request, and what must be approved by a person."]},
{heading:"Design requirements",bullets:["Explicit authorization at every boundary where user data or external actions are involved.","Observability for requests, tool calls, failures, and model behavior.","Failure isolation so one capability does not silently compromise the rest.","Clear provenance for retrieved information and generated outputs.","Human review for consequential or irreversible actions.","Versioned interfaces so components can evolve without breaking the ecosystem."]},
{heading:"How to read the system map",paragraphs:["Read the center as a coordination concept and the surrounding boxes as responsibilities. The lines indicate intended relationships, not necessarily synchronous calls or a fully implemented runtime topology. Implementation diagrams should identify concrete services, protocols, storage systems, trust boundaries, and deployment environments as those details become stable."]}
]},
{id:"architecture-cowork",category:"Architectures",title:"VANT CoWork system architecture",type:"MULTI-AGENT ARCHITECTURE · COWORK-004",summary:"A detailed architectural record of the CoWork coordination hub, persistent memory, negotiation board, task conversations, and hub internals.",date:"VANT RESEARCH DIVISION · ENGINEERING NOTE",sections:[
{heading:"System overview",paragraphs:["The CoWork architecture reference describes a coordinated workspace in which a person interacts through user and agent surfaces, a hub coordinates rooms and channels, peer agents discuss and divide work, and shared task and message systems preserve the work as it progresses.","The supplied system map groups the architecture into five major areas: User and Agent Surfaces; Room Coordination; Persistent Memory; Board and Negotiation; and Hub Internals. The diagram is a conceptual codebase architecture reference and should be checked against the current repository before being used as a live deployment map."]},
{heading:"1. User and agent surfaces",paragraphs:["The map identifies a Web UI and an Agent CLI under the User and Agent Surfaces group. A Person coordinates through these surfaces, while Peer Agents connect to the collaboration environment. The surfaces are entry points; they are not the coordination engine themselves."]},
{heading:"2. Room coordination",paragraphs:["The Room Coordination group contains the Hub API (main.py) and Rooms and Channels (room_channels.py). The Hub API provides the coordination entry point and hosts room structures. Rooms and channels give the work a place to live, helping separate task discussions and collaboration contexts."]},
{heading:"3. Persistent memory",paragraphs:["The Persistent Memory group contains Memory API (memory.py), a Markdown memory store (filesystem.py), and semantic memory search (search_index.py). The diagram shows the memory API persisting memories and supporting semantic search. This separation suggests two complementary responsibilities: durable storage of memory content and retrieval of relevant content by meaning.","Memory should be treated as contextual assistance, not unrestricted access. The implementation must preserve user and project boundaries, provide understandable controls, and avoid retrieving information into contexts where it does not belong."]},
{heading:"4. Board and negotiation",paragraphs:["The Board and Negotiation group contains Negotiation Aligner (aligner.py), Task Board (tasks.py), and Task Conversations (persister.py). The map depicts agents discussing tasks, claiming and splitting work, invoking a mediator, adding tasks, reading and posting, and opening task threads.","The board acts as a shared representation of work. Task conversations preserve the discussion around individual tasks. The Negotiation Aligner is shown as a coordinating component that helps agents reach a workable division of responsibility."]},
{heading:"5. Hub internals",paragraphs:["The Hub Internals group records the supporting modules that give the coordination layer its structure and runtime behavior."],bullets:["API Schemas (schemas.py) — defines API shapes.","Hub Configuration (config.py) — supplies configuration.","Message Envelopes (message_format.py) — formats messages.","SLIM Message Encoding (message_slim.py) — encodes messages.","In-memory Message Cache (in_memory_store.py) — updates and holds a message cache.","Message Models (message_models.py) — records message models.","Agent Model Sessions (api_session.py) — runs model sessions.","Agent Asks (asks.py) — represents agent asks.","Agent Registry (agent_registry.py) — records participants and agents.","Runtime Metrics (metrics.py) — records runtime measurements."]},
{heading:"Reading the connections",paragraphs:["The connections in the supplied diagram describe relationships such as message formatting and encoding, cache updates, model recording, session execution, participant lookup, task discussion, and persistence. The map should not be interpreted as proof that every agent always runs in parallel or that every connection is an independent network service.","The engineering value of this map is that it makes responsibilities and dependencies visible. It helps a developer ask where a message is shaped, where a task is persisted, where memory is retrieved, how agents coordinate, and where metrics are recorded."]}
]},
{id:"engineering-cowork",category:"Engineering",title:"Inside VANT CoWork: multi-agent orchestration",type:"ENGINEERING CASE STUDY · 004",summary:"The design of specialized agents, shared task context, controlled handoffs, persistence, and human review.",date:"VANT RESEARCH DIVISION · ENGINEERING NOTE",sections:[
{heading:"Why CoWork exists",paragraphs:["CoWork explores a different way to use AI at work. Instead of asking one general assistant to perform every part of a complex task in one uninterrupted response, the system organizes work into responsibilities that can be assigned, discussed, checked, and brought together.","The design direction is a coordinated multi-agent workspace—not a collection of independent chatbots. Agents should have clear roles, shared task context, and a defined way to contribute to a common outcome. Coordination is the feature; the number of agents is not the goal."]},
{heading:"The specialist team",paragraphs:["The documented CoWork preview defined seven roles. Each role represents a different contribution to the task lifecycle, and the team design is intended to make those responsibilities visible to the user."],bullets:["Planner — decomposes a request into manageable tasks and proposes an order of work.","Data Analyst — examines structured information and supports evidence-based analysis.","Researcher — gathers relevant information and prepares findings for the team.","Challenger — reviews assumptions, identifies gaps, and tests the quality of proposed work.","Connector — works with approved integrations and external sources within granted permissions.","Integrator — synthesizes specialist contributions into a coherent result.","Mote.EXE — the guardian/assistant identity that helps maintain a consistent VANT presence."]},
{heading:"Coordination and handoffs",paragraphs:["A task can begin with planning, move into specialist contributions, and return to an integration step where the work is synthesized. A challenger role can question assumptions or identify missing evidence. A human review checkpoint remains important when a decision or action has meaningful consequences.","The architecture reference includes a Planner, specialist agents, an Integrator, and Human Review. This is a conceptual handoff flow. It does not imply that all agents execute in parallel, nor that every task must pass through exactly the same sequence. The orchestrator should choose a workflow appropriate to the request."]},
{heading:"Persistence and shared context",paragraphs:["The CoWork design includes task records and conversations so that work does not disappear into a single transient chat response. The broader architecture map also identifies room and channel coordination, a task board, task conversations, memory services, message models, and runtime metrics.","Persistent state makes collaboration more useful, but it also increases responsibility. Task ownership, access control, retention, and visibility must be clear. A collaborator should see only the work they are authorized to access, and the system should not treat a prior task as permission to perform a new external action."]},
{heading:"Security and human review",paragraphs:["The documented preview stored agent profiles in a cowork_agent_profiles data model with Supabase Row Level Security. The preview also kept external actions disabled and required human review for consequential execution. These were deliberate safety boundaries in the preview design, not a claim that every future integration or production workflow is already secured.","A mature CoWork implementation needs explicit permission checks, scoped credentials, action previews, confirmation for high-impact operations, audit trails, and graceful failure handling. Agents should be able to propose work without silently gaining authority to execute it."]},
{heading:"What makes CoWork different",paragraphs:["The ambition is to make complex work legible. Users should be able to understand what the team is doing, why a specialist was involved, what evidence informed a result, which tasks remain open, and where human judgment is required. A successful multi-agent system is not merely autonomous; it is understandable, controllable, and useful."]}
]},
{id:"engineering-ai-engine",category:"Engineering",title:"The VANT AI engine: models, routing, and reliability",type:"ENGINEERING NOTE · AI-ENGINE-002",summary:"A record of VANT's model-integration experiments, provider changes, streaming issues, and the importance of graceful failure.",date:"VANT ENGINEERING · PLATFORM NOTES",sections:[
{heading:"The model is one part of the product",paragraphs:["VANT's AI engine has been developed through experiments with hosted model services and NVIDIA NIM. The product architecture separates the user-facing chat experience from the server-side request path so that model configuration can evolve without rebuilding every interface.","The early integration work used Google Gemma 4 31B IT through NVIDIA NIM. The engine was later adapted toward GPT-OSS 20B in pursuit of a faster interaction loop. NEMATRON 3 SUPER was also discussed as a model option during the evolution of the stack; it should not be read as a confirmed production default."]},
{heading:"Request path and streaming",paragraphs:["The VANT AI application uses a React and Vite frontend, with a Vercel serverless function at api/chat.js handling chat requests and communicating with the model provider. Streaming behavior matters because it shapes the perceived responsiveness of the product: the interface should display partial output reliably, handle completion, and recover cleanly when a provider fails.","During development, the chat experience required debugging around streamed replies, attachment handling, token limits, and provider responses. One observed failure occurred when GPT-OSS returned no text content, producing an NVIDIA NIM error. The issue was investigated and later resolved in the development process. The lesson is broader than one error: model responses need validation, and empty or malformed outputs must be handled as explicit failure states."]},
{heading:"Reliability principles",bullets:["Validate provider responses before treating them as completed assistant messages.","Handle empty content, timeouts, rate limits, and provider errors as distinct states.","Keep user-visible loading and retry behavior understandable.","Set appropriate token and attachment limits for the selected model.","Avoid coupling product logic to one provider's response format.","Record enough diagnostic information to troubleshoot failures without exposing secrets or private user content."]},
{heading:"Model choice is a product decision",paragraphs:["A model switch affects latency, reasoning quality, context capacity, cost, output formatting, and tool-use reliability. It should be evaluated against real VANT tasks: writing and analysis, spreadsheet assistance, document handling, student workflows, and multi-step CoWork tasks.","The long-term objective is a replaceable engine layer with clear model configuration and consistent application contracts. The interface should not need to know whether a particular response came from Gemma, GPT-OSS, or another supported model. Model availability and production defaults must be verified from the current deployment configuration before being stated as fact."]}
]},
{id:"engineering-platform",category:"Engineering",title:"Building the VANT Work Platform",type:"ENGINEERING NOTE · PLATFORM-001",summary:"The product architecture behind AI chat, projects, tools, memory, authentication, application state, and deployment.",date:"VANT ENGINEERING · PLATFORM NOTES",sections:[
{heading:"The product foundation",paragraphs:["The VANT AI Work Platform was developed as a web application using React and Vite, with the main interface organized around a primary AI chat experience. The product concept extends beyond chat: it brings together Projects, Tools, CoWork, Integrations, Dashboard, and Vant Memory so that users can move between asking, organizing, doing, and revisiting work.","The initial product structure placed AI Chat at the center and used a left navigation rail to expose the broader workspace. The design goal was a minimal, enterprise-oriented interface that feels capable without overwhelming the user."]},
{heading:"Application architecture",bullets:["Frontend — React and Vite, with the application interface developed in a focused App.jsx structure during the early build.","Authentication — Supabase Auth with email or magic-link access and OAuth options.","Backend request handling — Vercel serverless API route at api/chat.js for model requests.","AI provider integration — NVIDIA NIM, with model configurations evolving during development.","State and persistence — Supabase app_state records for selected application state, including theme, CoWork tasks and history, and integrations.","File handling — CSV and spreadsheet parsing work using PapaParse and related processing paths."]},
{heading:"Projects and collaboration",paragraphs:["Projects were designed to give work a persistent home. The project model included folders and role distinctions such as Owner, Collaborator, and Viewer, with separate project chat. This helps keep conversations and materials connected to a particular initiative rather than mixing every task into one general chat.","CoWork extends the collaboration idea from a project space into coordinated task execution. Tools and integrations provide specialized capabilities around the core chat experience. These areas should share consistent permission and state rules rather than becoming disconnected mini-applications."]},
{heading:"Guest access and product limits",paragraphs:["A Guest Mode experiment limited access to the AI Main Chat and enforced five messages per day on the server, with a reset at midnight Philippine time. After the limit, the API returned a 429 guest_limit_reached response. This was an early monetization and abuse-control design, not a statement about the current live plan configuration.","The broader tier discussion considered Guest, Free, Pro, and Enterprise access, with feature gates for chat history, Tools, CoWork, Projects, Dashboard, and Integrations. Any current pricing or entitlement policy must be checked against the deployed product before publication."]},
{heading:"Deployment and debugging lessons",paragraphs:["The project encountered practical integration issues: Supabase hostname and DNS resolution problems, preview-versus-production confusion in Vercel, model-provider errors, and attachment rendering issues. These were not merely isolated inconveniences. They reinforced the need to distinguish environments, verify deployment targets, and test complete user flows rather than relying on a successful build alone.","A green deployment indicates that a build completed. It does not by itself prove that authentication, model requests, database policies, file uploads, or every route works correctly. Production changes should be intentional, traceable, and separately verified."]}
]},
{id:"engineering-mote",category:"Engineering",title:"MOTE.EXE: identity, behavior, and interface presence",type:"DESIGN SYSTEM · MOTE-001",summary:"The identity of VANT's watchful assistant: a serious, quiet guardian presence expressed through consistent visual and interaction principles.",date:"VANT DESIGN · IDENTITY NOTE",sections:[
{heading:"Identity",paragraphs:["Mote, with the full designation Mote.EXE, is the assistant identity associated with VANT. The character is described as serious and watchful, with a guardian-like presence. It is not designed to be a smiling mascot or a loud personality competing with the user's work.","The visual language centers on a black orb-like form, pointed ears, and a white geometric visor or eye treatment divided by a central black bridge or slit. The preferred direction is clean and graphic, with a restrained silhouette rather than a generic glossy 3D character."]},
{heading:"Behavioral character",bullets:["Watchful — attentive to context without demanding attention.","Composed — calm, precise, and measured in its communication.","Protective — reinforces boundaries, review, and safe handling of consequential actions.","Quietly capable — communicates competence through useful behavior rather than theatrics.","Consistent — retains the same identity across the VANT ecosystem."]},
{heading:"Visual environment",paragraphs:["MOTE experiences use a dark graphite environment with cool ambient light, restrained highlights, and a technical atmosphere. Orbiting channels, rings, and connected elements can communicate system activity and coordination. The preferred mood is dimensional and atmospheric, not flat black and not excessively decorative.","The same visual language should carry across the MOTE product page, chat presence, dashboard, and related experiences. MOTE should feel like part of VANT's system identity rather than a separate cartoon brand."]},
{heading:"A guardian, not an authority bypass",paragraphs:["The guardian concept is an identity and interaction principle. It does not grant the assistant special permissions or remove the need for human confirmation. MOTE should help users understand what is happening, surface relevant context, and respect the same access and approval boundaries as the rest of VANT."]}
]},
{id:"patch-platform",category:"Patch Notes",title:"Platform foundations: authentication, chat, and state",type:"DEVELOPMENT HISTORY · PLATFORM",summary:"A historical record of foundational VANT platform work and the reliability issues addressed during development.",date:"VANT TECHNOLOGIES · DEVELOPMENT LOG",sections:[
{heading:"Foundational application work",paragraphs:["The early VANT platform established the React and Vite application shell, the main AI chat experience, and the connection to a server-side chat endpoint. Supabase Auth was selected for account access, including email or magic-link and OAuth flows. Supabase also provided a place to persist application state.","The app_state model was used to organize selected state such as theme, CoWork tasks, CoWork history, and integrations. This helped move the experience beyond a single local interface toward a persistent application."]},
{heading:"Chat and model integration",paragraphs:["The chat implementation went through streaming-response debugging, token-limit adjustments, model-provider changes, and handling for empty model output. A notable GPT-OSS/NVIDIA NIM failure returned no text content; the response path was adjusted during the development cycle to address the issue.","Attachment work also exposed interface details that matter to real users: CSV data should not overwhelm the conversation, image attachments should have visible previews, and file content should be presented in a way that supports the task rather than taking over the chat."]},
{heading:"Access and usage controls",paragraphs:["Guest Mode introduced a server-enforced daily message limit. The five-message cap and midnight Philippine-time reset were implemented as a controlled access experiment. The API returned a dedicated guest_limit_reached response after the allowance was consumed.","The key engineering lesson is that usage limits belong on the server, not only in the interface. A visible counter can help users understand a limit, but the API must enforce it."]},
{heading:"Environment discipline",paragraphs:["Vercel preview and production environments were a recurring source of confusion during development. The working practice that emerged is to verify the branch, commit, deployment target, and ready state before calling a change complete. A preview deployment is a safe place to inspect a change; it should not be described as production.","Supabase connectivity and DNS errors also demonstrated that a healthy frontend build does not guarantee that external services are reachable. The full request path needs to be checked."]}
]},
{id:"patch-website",category:"Patch Notes",title:"VANT Technologies website: identity and knowledge experience",type:"DEVELOPMENT HISTORY · WEB",summary:"A record of the corporate website direction, dedicated routes, newsroom, Document Viewer, Research, and Jamboard.",date:"VANT TECHNOLOGIES · WEBSITE JOURNAL",sections:[
{heading:"Corporate identity and homepage",paragraphs:["The VANT Technologies website was developed around a restrained editorial identity: warm ivory, charcoal, cool silver, and slate. Earlier gold accents were retired in favor of a quieter graphite-and-silver palette. The homepage structure was deliberately limited to Mission and Vision, the MOTE.EXE hero, the product ecosystem, and a section introducing VANT Technologies resources, with a global mega footer for navigation.","The mission and vision statement combines the belief that intelligent technology and thoughtful design can make work more capable, learning more personal, and ambitious ideas more achievable. The visual direction favors generous space, measured typography, and a calm enterprise presence."]},
{heading:"Navigation and dedicated destinations",paragraphs:["The navigation system was organized around News, Research, Policy, Commitments, Company, Products, SELLSPACE, and Let's Connect. Category dropdowns use an editorial split layout: a larger introductory panel and a set of destination cards. Outside-click and Escape behavior were added so menus can be dismissed naturally.","Dedicated destinations were created for major corporate categories and topics so links would not fall back to the default homepage. These include News, Research, Policy, Commitments, Company, Products, Perspectives, Our Approach, Mission, Vision, Partnerships, and Education, alongside dedicated Libraries, Connect, Legal, and MOTE pages."]},
{heading:"Newsroom and Document Viewer",paragraphs:["The newsroom direction uses compact story cards that open a floating VANT / Document Viewer rather than forcing the reader through a separate route for every story. The viewer uses a dark graphite frame, a light reading surface, a clear document title, metadata, and a related VANT Libraries reference. Patch notes are positioned above the footer so release information remains part of the newsroom experience.","The Document Viewer became a reusable presentation pattern for reading product updates, engineering notes, and other long-form material without losing the surrounding page context."]},
{heading:"Research and Jamboard",paragraphs:["Research adopted a scientific and engineering visual direction. A featured CoWork case-study card introduces the multi-agent orchestration architecture and opens the full engineering note in the Document Viewer.","VANT / Jamboard was introduced as a separate visual architecture viewer for diagrams, technical systems, workflows, and engineering blueprints. Its graphite workspace, steel-blue lines, grid, zoom controls, information toggle, and explicit exit control keep the diagram central. The CoWork system map records the architecture reference supplied during development, including user surfaces, coordination, memory, negotiation, task persistence, and hub internals."]},
{heading:"A living website",paragraphs:["The corporate website is developed through preview branches and incremental changes. A successful preview build is an important checkpoint, but individual routes and interactive behaviors still need browser verification. Production remains a separate release decision."]}
]},
{id:"architecture-jamboard",category:"Architectures",title:"VANT / Jamboard: visual architecture viewer",type:"INTERACTIVE SYSTEM VIEW · JAM-001",summary:"A dedicated canvas for exploring system diagrams, component relationships, technical workflows, and engineering blueprints.",date:"VANT RESEARCH · INTERFACE SPECIFICATION",sections:[
{heading:"Purpose",paragraphs:["Jamboard is the visual counterpart to the VANT Document Viewer. The Document Viewer is for reading knowledge; Jamboard is for examining systems. It is intended to give architecture diagrams enough room to be understood without burying them under a large title or description panel.","The visual reference uses a graphite workspace, steel-blue connection paths, a fine technical grid, restrained glow, and compact controls. The diagram—not the interface—is the primary object."]},
{heading:"Interaction model",bullets:["Zoom controls for closer inspection and a FIT action to return to a useful whole-board view.","An information button that reveals the board title, summary, and contextual description only when needed.","A clear EXIT control that closes the viewer and returns the user to the page they came from.","A scrollable or pannable canvas for diagrams taller or wider than the available viewport.","Future component-level inspection, layer toggles, and export or sharing capabilities are planned enhancements, not assumed to be complete."]},
{heading:"Architecture content",paragraphs:["The CoWork board is based on the detailed architecture reference supplied during development. It includes the Web UI and Agent CLI, Hub API, Rooms and Channels, Memory API, Markdown memory store, semantic memory search, Negotiation Aligner, Task Board, Task Conversations, and hub-internal modules for schemas, configuration, message formats, encoding, cache, models, sessions, asks, registry, and metrics.","When diagrams are reconstructed as vector or interactive visualizations, their labels and relationships should be checked against the source. The visualization should preserve the distinction between a conceptual relationship and a verified runtime call."]}
]},
{id:"guide-product",category:"Guides & Resources",title:"How to explore VANT Libraries",type:"USER GUIDE · LIBRARY",summary:"A short guide to categories, search, document selection, and the reading experience.",date:"VANT LIBRARIES · USER GUIDE",sections:[
{heading:"Find a topic",paragraphs:["Use the Library Index on the left to browse News, Architectures, Engineering, Patch Notes, Policies, and Guides & Resources. Select a category to filter the document list. Choose All resources to return to the full collection."]},
{heading:"Search across the collection",paragraphs:["Enter a phrase in the search field to find matching document titles, summaries, categories, types, and article text. Clear the field to restore the selected category's full list. Search is intended to help readers find a topic without knowing its exact category in advance."]},
{heading:"Read in Document Viewer",paragraphs:["Select a document card in the middle column. Its content appears in VANT / Document Viewer on the right. The viewer keeps the document inside the Libraries workspace, so readers can move between resources without navigating away from the collection.","Documents may include a summary, sections, lists, related category, and publication or preparation status. A policy marked In Preparation is not a published policy and should not be relied upon as an effective legal notice."]}
]},
{id:"guide-reference",category:"Guides & Resources",title:"Technical references and glossary",type:"REFERENCE · KNOWLEDGE",summary:"A growing vocabulary for the systems, components, and product concepts used across VANT.",date:"VANT LIBRARIES · REFERENCE",sections:[
{heading:"AI Work Platform",paragraphs:["The VANT application concept that brings AI chat, Projects, Tools, CoWork, Integrations, Dashboard, and Vant Memory into one work environment."]},
{heading:"CoWork",paragraphs:["A coordinated workspace concept in which specialist agents contribute to shared tasks through planning, discussion, persistence, synthesis, and human review."]},
{heading:"Semantic core",paragraphs:["A proposed shared intelligence layer that coordinates context, reasoning, memory, orchestration, specialist capabilities, and interfaces across the VANT ecosystem."]},
{heading:"Document Viewer",paragraphs:["A reusable floating reading surface for newsroom stories, patch notes, engineering notes, and other long-form documents."]},
{heading:"Jamboard",paragraphs:["A visual architecture viewer for diagrams, technical systems, workflows, and engineering blueprints."]},
{heading:"MOTE.EXE",paragraphs:["The watchful guardian/assistant identity associated with VANT. MOTE is a product identity and interaction presence, not a separate authorization system."]}
]},
{id:"guide-research",category:"Guides & Resources",title:"Research perspectives and reading principles",type:"RESEARCH · EDITORIAL GUIDE",summary:"How VANT documents engineering ideas, proposed architectures, implementation records, and external references.",date:"VANT LIBRARIES · RESEARCH PRACTICE",sections:[
{heading:"Separate concept from implementation",paragraphs:["A proposed architecture describes an intended design. An implementation note records work that has been built or tested. A release note records a change that has been shipped to a stated environment. These are different kinds of evidence and should be labeled accordingly."]},
{heading:"Preserve provenance",paragraphs:["When a diagram, external article, or technical source informs a VANT document, retain its origin and identify which details came from the source. Reconstructed diagrams should not quietly add components or claim relationships that were not present in the reference."]},
{heading:"Make engineering understandable",paragraphs:["The purpose of a research note is not to make a system sound more advanced than it is. It is to explain the problem, the design, the trade-offs, the current state, and the questions that remain. Useful documentation should help another person understand and challenge the work."]}
]},
{id:"policy-terms",category:"Policies",title:"Terms and Agreement",type:"POLICY · TERMS",summary:"Planned terms governing access to and use of VANT websites, products, and services.",date:"VANT TECHNOLOGIES · POLICY LIBRARY",status:"IN PREPARATION",sections:[
{heading:"Publication status",paragraphs:["This entry is a policy planning record. It is not an effective agreement, does not create contractual terms, and must not be presented as published legal terms."]},
{heading:"What the final document must cover",bullets:["The correct legal entity and contact details responsible for each service.","Covered websites, applications, products, and services.","Account creation, eligibility, access, and user responsibilities.","Acceptable use, prohibited conduct, and security requirements.","Intellectual property and user-submitted content.","Service availability, changes, suspension, and termination.","Disclaimers, liability limits, dispute handling, and governing law.","A clear effective date and version history."]},
{heading:"Review required",paragraphs:["The final agreement must be reviewed against the actual VANT product behavior and applicable law before publication."]}
]},
{id:"policy-privacy",category:"Policies",title:"Data and Privacy for VANT Applications",type:"POLICY · PRIVACY",summary:"Planned privacy documentation for the collection, use, retention, and protection of information across VANT applications.",date:"VANT TECHNOLOGIES · POLICY LIBRARY",status:"IN PREPARATION",sections:[
{heading:"Publication status",paragraphs:["This entry is a planning record, not a published privacy notice. It does not make a definitive claim about every data flow in VANT applications. The final policy must be based on a verified application-by-application data inventory."]},
{heading:"Required data inventory",bullets:["Account and authentication data handled through Supabase Auth.","User content such as chats, project materials, task records, and uploaded files.","Application state and preferences, including any persisted workspace settings.","Model-provider requests and the data transmitted to external AI services.","Connected integrations and any data exchanged with those services.","Operational logs, security events, diagnostics, and analytics, if used."]},
{heading:"Required policy disclosures",bullets:["Purposes and lawful bases for processing, where applicable.","Data processors, hosting providers, and international transfers.","Retention periods and deletion procedures.","User access, correction, deletion, and other applicable rights.","Security controls and incident-response procedures.","Age eligibility and protections for younger users.","Contact details for privacy questions and requests."]},
{heading:"Verification before publication",paragraphs:["The policy must be checked against live infrastructure, provider contracts, database policies, logs, and actual retention behavior. A design intention is not proof that a control is deployed."]}
]},
{id:"policy-child-safety",category:"Policies",title:"Child Cyber Safety",type:"POLICY · SAFETY",summary:"Planned safeguards and age-appropriate principles for younger users and educational experiences.",date:"VANT TECHNOLOGIES · POLICY LIBRARY",status:"IN PREPARATION",sections:[
{heading:"Purpose",paragraphs:["This document is planned to define how VANT approaches online safety for younger users, particularly in learning-related experiences. It is not a claim that a complete child-safety program is currently implemented."]},
{heading:"Areas to define",bullets:["Minimum age requirements and age-appropriate access.","Parent or guardian involvement where required.","Clear reporting routes for harmful or inappropriate content.","Moderation, escalation, and response procedures.","Data minimization and privacy protections for minors.","Safe defaults for sharing, messaging, and external integrations.","Guidance for educators, parents, and users."]},
{heading:"Design principle",paragraphs:["Safety requirements should be designed into product flows and permissions from the beginning, not added only as a policy statement after launch. The final policy must match the actual product controls and applicable child-protection requirements."]}
]},
{id:"policy-ai",category:"Policies",title:"Policy on AI Exponential",type:"POLICY · AI GOVERNANCE",summary:"Planned principles for responsible AI development, model use, transparency, evaluation, and human oversight.",date:"VANT TECHNOLOGIES · POLICY LIBRARY",status:"IN PREPARATION",sections:[
{heading:"Publication status",paragraphs:["This is a planning entry. The title 'Policy on AI Exponential' is retained from the requested category list; its final name, scope, and requirements should be reviewed before adoption."]},
{heading:"Governance topics",bullets:["Model selection, evaluation, and change management.","Transparency about AI-generated outputs and limitations.","Human oversight and confirmation for consequential actions.","Data governance, privacy, and information security.","Testing for reliability, misuse, and harmful outcomes.","Monitoring, incident reporting, and corrective action.","Third-party model and integration risk management."]},
{heading:"Core position",paragraphs:["AI capability should expand human agency, not obscure accountability. The final policy should state which decisions remain with people, what actions systems may perform, and how users can understand, challenge, or report an output."]}
]},
{id:"policy-cookies",category:"Policies",title:"Cookies and Technology",type:"POLICY · COOKIES",summary:"Planned disclosures for cookies, local storage, analytics, and similar technologies used by VANT properties.",date:"VANT TECHNOLOGIES · POLICY LIBRARY",status:"IN PREPARATION",sections:[
{heading:"Publication status",paragraphs:["This is a planning entry, not a published cookie notice. The final version must reflect the technologies actually deployed on each VANT website and application."]},
{heading:"Technology inventory",bullets:["Strictly necessary cookies and session mechanisms, if used.","Preference storage such as theme or interface settings.","Analytics and performance measurement technologies, if enabled.","Embedded third-party content and integration technologies.","Local storage and other browser-side persistence mechanisms."]},
{heading:"Required disclosures",paragraphs:["For each technology, document its purpose, provider, duration, data involved, and available user controls. Do not claim that a cookie banner, consent mechanism, or analytics opt-out exists unless it has been implemented and verified."]}
]}
];
